--region init
function ActivityBossChallengeDialog:InitHandler()
    SetButtonAction(self.BtnTask, Bind(self, self.BtnTaskOnClickHandler))
    SetButtonAction(self.RewardBtn, Bind(self, self.RewardBtnOnClickHandler))

    self._receiveTaskRewardsEvent = Events.AddListener(Constants.EventNames.ActivityBossChallengeReceiveTaskRewards, Bind(self, self.ReceiveTaskRewardsEventHandler))
    self._refreshEvent = Events.AddListener(Constants.EventNames.ActivityDialogRefresh, Bind(self, self.RefreshEventHandler))
end

function ActivityBossChallengeDialog:InitData()
    local argument = self.controller.Argument.parameters
    self._activityId = checkInt(argument.activityId)
    GameUtils.Request(Interfaces.ActivityBossChallengeHome, {activityUuid = self._activityId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self._homeData = self:ConvertHomeData(response.data)
        self:InitView()
    end)
end

function ActivityBossChallengeDialog:InitView()
    activityMgr:GetActivityComponent():SetActivityEnterTime(self._activityId)
    
    if not self.ScrollViewList.IsListViewInit then
        self.ScrollViewList:InitListView(#self._homeData.scheduleConf, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollViewList, #self._homeData.scheduleConf)
    end
    KTool.SetActive(self.ProgressGroup, true)
    
    self:RefreshRewards()
    self:RefreshTaskRedPoint()
    self:CalculateListPos()
end
