--region handler
---任务按钮点击回调
function ActivityBossChallengeDialog:BtnTaskOnClickHandler()
    UIModule.OpenDialog({ 
        id = Constants.UITypeIds.ActivityBossChallengeRewardDialog, 
        parameters = {
            playerPointRewards = self._homeData.playerPointRewards, 
            playerPointNum = self._homeData.playerPointNum,
            activityId = self._activityId,
        }
    })
end

---全服奖励领取按钮点击回调
function ActivityBossChallengeDialog:RewardBtnOnClickHandler()
    local index = self:GetNextServerRewardIndex()
    if index > #self._homeData.serverRewards then return end

    local curNum = checkInt(self._homeData.serverPointNum)
    local needNum = self._homeData.serverRewards[index].needNum
    if curNum < needNum then
        GameUtils.Toast(localize("点数不足"))
        return 
    end
    
    GameUtils.Request(Interfaces.ActivityBossChallengeServerDrawReward, {activityUuid = self._activityId}, Bind(self, self.ServerDrawRewardResponseHandler))
end

---领取全服奖励回调处理
function ActivityBossChallengeDialog:ServerDrawRewardResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    -- 领取奖励
    GoodsUtils.DrawRewards(response.data.rewards)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })
    
    -- 更新本地数据
    local index = self:GetNextServerRewardIndex()
    self._homeData.drawServerRewardId = self._homeData.serverRewards[index].id
    self:RefreshRewards()
end

---列表刷新
function ActivityBossChallengeDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, CellScrPath)
    if nodeEnv then
        local luaIndex = index + 1
        local data = self._homeData.scheduleConf[luaIndex]
        data.remainQuestNum = self._homeData.remainQuestNum
        nodeEnv:RefreshCell(data)
        nodeEnv:SetBtnCallBack(function()
            if checkInt(self._homeData.remainQuestNum) <= 0 then
                GameUtils.Toast(localize('挑战次数不足'))
                return
            end
            local questData = self:GetQuestData(data.group)
            UIModule.OpenDialog({
                id = Constants.UITypeIds.ActivityBossChallengeDifficultyDialog,
                parameters = {
                    questData  = questData,
                    activityId = self._activityId,
                    scheduleId = data.scheduleId,
                    activityScheduleId = self._homeData.activityId,
                    enterAnimation = self:GetEnterAniByCellIndex(luaIndex)
                }
            })
        end)
    end
    return cell
end

---领取任务奖励事件处理
function ActivityBossChallengeDialog:ReceiveTaskRewardsEventHandler(id)
    for i, v in ipairs(self._homeData.playerPointRewards) do
        if checkInt(v.id) == checkInt(id) then
            v.status = Constants.GetStatus.Has
            break
        end
    end
    self:RefreshTaskRedPoint()
end

---每日刷新事件处理
function ActivityBossChallengeDialog:RefreshEventHandler()
    GameUtils.Request(Interfaces.ActivityBossChallengeHome, {activityUuid = self._activityId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self._homeData = self:ConvertHomeData(response.data)
        self:InitView()
    end)
end

---定时器处理
function ActivityBossChallengeDialog:TimerHandler()
    for i, data in ipairs(self._homeData.scheduleConf) do
        local go = self.ScrollViewList:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, CellScrPath)
            scr:RefreshCountdown()
        end
    end
end
--endregion handler

--region private
---转换home数据
function ActivityBossChallengeDialog:ConvertHomeData(responseData)
    local homeData = checkTable(responseData)
    local serverTime = GameUtils.GetServerTime()
    for _, v in ipairs(checkTable(homeData.scheduleConf)) do
        v.endTime = checkInt(v.endTime) + serverTime
        v.startTime = checkInt(v.startTime) + serverTime
    end
    
    local serverRewards = {}
    for _, v in pairs(homeData.serverRewards) do
        table.insert(serverRewards, v)
    end
    table.sort(serverRewards, function(a, b)  
        return checkInt(a.needNum) < checkInt(b.needNum)
    end)
    homeData.serverRewards = serverRewards
    return homeData
end

---计算列表坐标（当cell不足4个的时候，要居中显示）
function ActivityBossChallengeDialog:CalculateListPos()
    local cellNum = #self._homeData.scheduleConf
    local deltaX = 0
    local sizeDelta = self.ListViewport.transform.sizeDelta
    local anchoredPosition = self.ListViewport.transform.anchoredPosition
    if cellNum < 4 then
        -- 居中
        local listW = self.ScrollViewList.transform.rect.width
        local cellW = self.Cell.transform.rect.width 
        local deltaW = listW / 2 - cellW / 2 - (cellNum - 1) * (cellW - 30) / 2
        deltaX = deltaW
    end
    sizeDelta.x = -deltaX
    self.ListViewport.transform.sizeDelta = sizeDelta
    anchoredPosition.x = deltaX
    self.ListViewport.transform.anchoredPosition = anchoredPosition
end

---开启定时器
function ActivityBossChallengeDialog:StartTimer()
    TimerModule.Instance:AddTimer(Constants.TimerName.ActivityBossChallengeTimer, 0, 1, Bind(self, self.TimerHandler))
end

---刷新全服奖励
function ActivityBossChallengeDialog:RefreshRewards()
    local index = self:GetNextServerRewardIndex()

    local curNum = checkInt(self._homeData.serverPointNum)
    local needNum = nil
    local canReceive = nil
    if index > #self._homeData.serverRewards then
        needNum = self._homeData.serverRewards[#self._homeData.serverRewards].needNum
        canReceive = false
    else
        needNum = self._homeData.serverRewards[index].needNum
        canReceive = curNum >= needNum
    end

    CfUtils.FillText(self.TxtProgressNumber, string.format("<size=36>%d/</size>%d", curNum, needNum))
    self.ImgSliderFill.fillAmount = math.min(1, curNum / needNum)
    
    CfUtils.SetActive(self.UIFX_BossFightDialogRewarEffect, canReceive)
    CfUtils.SetUISwitchImage(self.ImgNumberBg, canReceive and 2 or 1)
    CfUtils.SetUISwitchText(self.TxtNumber, canReceive and 2 or 1)
    CfUtils.SetActive(self.RewardRedPoint, canReceive)
    
    -- UI上只能显示一个道具，但是后端支持配置多个，所以这里只取第一个作为显示道具
    if index > #self._homeData.serverRewards then
        -- 所有奖励全部领取
        CfUtils.SetActive(self.FinishNode, true)
        CfUtils.SetActive(self.TxtNumber, false)
        CfUtils.SetActive(self.ImgNumberBg, false)
        local rewards = self._homeData.serverRewards[index - 1].rewards[1]
        CfUtils.FillImage(self.RewardIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(rewards.goodsId))
        CfUtils.FillImage(self.ImgIconFinish, GoodsConfMgr:GetInstance():GetPhotoPathById(rewards.goodsId))
    else
        CfUtils.SetActive(self.FinishNode, false)
        CfUtils.SetActive(self.TxtNumber, true)
        CfUtils.SetActive(self.ImgNumberBg, true)
        local rewards = self._homeData.serverRewards[index].rewards[1]
        CfUtils.FillText(self.TxtNumber, "x" .. tostring(rewards.num))
        CfUtils.FillImage(self.RewardIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(rewards.goodsId))
    end
    
    -- 播放动画
    if canReceive then
        self.ProgressGroup:Play("UIBossFightDialogRewardCanTake")
    else
        self.ProgressGroup:Play("UIBossFightDialogRewardIdle")
    end
end

---刷新任务红点
function ActivityBossChallengeDialog:RefreshTaskRedPoint()
    local canReceive = false
    for i, v in ipairs(self._homeData.playerPointRewards) do
        if checkInt(v.status) == Constants.GetStatus.Can then
            canReceive = true
            break
        end
    end
    
    CfUtils.SetActive(self.TaskRedPoint, canReceive)
end

---获取下一阶段全服奖励索引
function ActivityBossChallengeDialog:GetNextServerRewardIndex()
    local drawServerRewardId = checkInt(self._homeData.drawServerRewardId)
    local index = 1
    if drawServerRewardId > 0 then
        for i, v in ipairs(self._homeData.serverRewards) do
            if checkInt(v.id) == drawServerRewardId then
                index = i + 1
                break
            end
        end
    end
    return index
end

---获取关卡数据
function ActivityBossChallengeDialog:GetQuestData(groupId)
    local questVo = CfUtils.GetCf(AutoIds.IdSetting2751, "BossChallengeQuestVo", true)
    local questList = {}
    for _, v in ipairs(questVo) do
        if checkInt(v.group) == checkInt(groupId) then
            table.insert(questList, v)
        end
    end
    table.sort(questList, function(a, b)
        return checkInt(a.regionLevel) < checkInt(b.regionLevel)
    end)
    return questList
end

---获取难度界面入场动画
function ActivityBossChallengeDialog:GetEnterAniByCellIndex(index)
    local go = self.ScrollViewList:GetShownItemByItemIndex(index - 1)
    if not isNull(go) then
        local offsetPos = UIModule.RootCanvas.transform:TransformPoint(go.transform.rect.width / 2, 0, 0)
        local goPos = Vector3.New(go.transform.position.x + offsetPos.x, go.transform.position.y, 0)
        local uiCam = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("UI"))
        local screenPos = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(uiCam, goPos)
        if screenPos.x < SCREEN_WIDTH / 3 then
            return EnterAnimationType.LEFT
        elseif screenPos.x < SCREEN_WIDTH * 2 / 3 then
            return EnterAnimationType.MIDDLE
        else
            return EnterAnimationType.RIGHT
        end
    end
end
--endregion private

return ActivityBossChallengeDialog